public class PrimitiveDataTypes {
    public static void main(String[] args) {
        byte a = 10;
        short b = 128;
        int c = 32768;
        long d = 2147483648L;
        float e = 3.147F;
        double g = 22.3456789012;
        char h = 'A';
        System.out.println(a + " " + b + " " + c + " " +
                           d + " " + e + " " + g + " " + h);
    } }

